/// One attachment on an inbound message.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
pub struct InboundMediaWebhookPayload {
    /// Where the carrier hosts the attachment.
    ///
    /// This link expires and is not authenticated. sent.dm relays it rather than copying
    /// the file, so how long it stays fetchable is the carrier's decision and differs between them —
    /// assume days, not months. Anyone holding the URL can fetch it until it lapses. Copy the file on
    /// receipt if you need it to outlive that window; do not store this URL as a permanent reference.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub url: Option<String>,
    /// Content type as the carrier reported it, for example image/jpeg.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mime_type: Option<String>,
    /// Size in bytes as the carrier declared it. Absent when it declared none.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub size_bytes: Option<i64>,
    /// SHA-256 of the file as the carrier declared it, when it declares one. Verify what you download
    /// against this — sent.dm never reads the bytes, so it is the only integrity signal available.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub hash_sha256: Option<String>,
}

/// Body of a message.received event. Delivered when a contact messages one of your numbers.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
pub struct InboundMessageEventPayload {
    /// The inbound message.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub message_id: Option<String>,
    /// When the message was received, in UTC (yyyy-MM-ddTHH:mm:ssZ). Same value as
    /// ReceivedAt, kept for envelope consistency with outbound events.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub updated_at: Option<String>,
    /// The account the message belongs to.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub account_id: Option<String>,
    /// The contact's number in E.164 format, meaning the number the message came from.
    pub inbound_number: String,
    /// Your number in E.164 format, meaning the number the message was addressed to.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub outbound_number: Option<String>,
    /// The message body. Sent as null when the inbound message carried no text, for
    /// example a media-only message. The field is always present, so read it and check for null
    /// rather than checking whether the key exists.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub text: Option<String>,
    /// The channel the message arrived on, for example sms or mms.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub channel: Option<String>,
    /// Attachments the contact sent, present only on channels that carry them (mms today) and
    /// omitted entirely otherwise.
    ///
    /// Each url points at the carrier's own copy of the file — sent.dm records where the
    /// attachment is, not the attachment itself. The link is unauthenticated and expires on the
    /// carrier's schedule, which differs between them: assume days, not months. Download what you need
    /// on receipt; re-reading the message through GET /v3/messages/{id} returns the same stored
    /// link, not a fresh one, so once it lapses the entry remains with whatever the carrier declared
    /// about the file but the file is no longer reachable.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub media: Option<Vec<InboundMediaWebhookPayload>>,
    /// The ad the contact tapped to start the conversation, present only on whatsapp
    /// messages sent from a Click to WhatsApp ad and omitted entirely otherwise.
    ///
    /// This is Meta's referral object passed through unchanged, with Meta's field names and
    /// nesting: source_url, source_id, source_type, headline, body,
    /// media_type, image_url (image ads), video_url and thumbnail_url (video
    /// ads), ctwa_clid and welcome_message.text. Which fields appear is Meta's decision:
    /// ctwa_clid in particular is not sent for ads shown in WhatsApp Status, so treat every field
    /// as optional.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub referral: Option<SystemTextJsonJsonElement>,
    /// When the message was received, in UTC (yyyy-MM-ddTHH:mm:ssZ).
    pub received_at: String,
}

